def tensor_norm_fields(tensor, prefix=''):
    x = tensor.detach().float()
    squared_sum = x.square().sum().item()
    return {f'{prefix}fro_norm': math.sqrt(squared_sum),
            f'{prefix}rms_norm': math.sqrt(squared_sum / x.numel())}

